CATEGORIES=['Инициализация','Константность','Ссылки','Составные операции','Методы и параметры','Свободные операторы','Дружба','Изменяемая индексация','Константная индексация','Вызов объекта','Инкремент','Время жизни','Потоковый вывод','Ошибки ввода','Семантика операций','Числовой допуск']
for number in range(1,17):
    block=re.search(rf'^### Q{number:02}\. (.+?)\n(.*?)(?=^### Q|^## 4\.)',SOURCE,re.M|re.S)
    title,body=block[1],block[2]
    visible=re.split(r'\*\*(?:Ключ|Проверяющий):\*\*',body,maxsplit=1)[0].strip()
    markers=list(re.finditer(r'(?<!\w)([ABCD])\.\s+',visible))
    if [m[1] for m in markers]!=list('ABCD'):raise ValueError(f'Bad Q options {number}')
    prompt=visible[:markers[0].start()].strip()
    options=[visible[m.end():markers[i+1].start() if i+1<len(markers) else len(visible)].strip().rstrip(';').strip() for i,m in enumerate(markers)]
    add('Q',number,f'Q{number:02} · {title}',prompt,options=options,answer=[ANSWERS[number-1]],explanation=EXPLANATIONS[number-1],optionExplanations=OPTION_EXPLANATIONS[number-1],multiple=False,runner='choice',category=CATEGORIES[number-1],difficulty='Средняя' if number in (4,9,11,12,14,16) else 'Базовая')

