OUTPUTS=['7','9:9','5 7 7','7 2','7 7','12 1']
for number in range(1,7):
    block=re.search(rf'^### P{number:02}\. (.+?)\n(.*?)(?=^### P|^## 6\.)',SOURCE,re.M|re.S)
    source=re.search(r'```cpp\n(.*?)```',block[2],re.S)[1]
    trace=TRACES[number-1]
    fields=[dict(id=key,label=label,**({'options':CHOICES[key]} if key in CHOICES else {})) for key,label,_ in trace]
    answers={key:value for key,_,value in trace}
    alternate=source
    alternate_answers=dict(answers)
    alternate_output=OUTPUTS[number-1]
    if number==1:
        alternate=source.replace('int a = 4','int a = 9');alternate_answers.update(after_f='9',after_g='12');alternate_output='12'
    elif number==2:
        alternate=source.replace('Box a(4)','Box a(2)').replace('b.v = 9','b.v = 6');alternate_answers.update(after_copy='2',original_after_edit='2');alternate_output='6:6'
    elif number==3:
        alternate=source.replace('Counter x(5)','Counter x(11)');alternate_answers.update(after_postfix='12',saved_a='11');alternate_output='11 13 13'
    elif number==4:
        alternate=source.replace('a(1), b(2), c(4)','a(3), b(5), c(-2)');alternate_answers.update(after_first='8',after_second='6');alternate_output='6 5'
    elif number==5:
        alternate=source.replace('{3, 7}','{-2, 5}');alternate_answers.update(second_value='5');alternate_output='5 5'
    else:
        alternate=source.replace('12 x 8','15 bad 3');alternate_output='15 1'
    add('P',number,f'P{number:02} · Трассировка {number}', 'Запишите точный вывод и своими словами объясните причины. Затем заполните проверяемую трассировку. Оценка причин опирается на значения и причинные утверждения, а не на поиск слов в тексте.',code=source,runner='prediction',traceFields=fields,expectedOutput=OUTPUTS[number-1],traceAnswer=answers,explanation=P_EXPLANATIONS[number-1],variants=[dict(code=alternate,expectedOutput=alternate_output,traceAnswer=alternate_answers,explanation='Примените те же правила копирования, ссылок и порядка операций к новым значениям. '+P_EXPLANATIONS[number-1])])
